# 7급 CH9 조동사 Can (81~90) 2차 감수
X(7, 81, r="평서문에서 can은 주어 바로 뒤, 동사원형 바로 앞에 둔다.",
  n=["can이 주어(My mom)보다 앞에 오므로", "can이 주어(My mom) 가운데에 끼므로", "주어(My mom) 뒤, 동사(bake) 앞이라 can이 들어갈 자리이므로", "동사(bake)보다 뒤이므로", "문장 맨 끝이므로"],
  st="① 주어가 어디까지인지 찾는다: {0}. → ② 그다음에 오는 동사를 찾는다: {1}. → ③ can은 주어와 동사 사이에 들어가므로 동사 앞 번호인 {n}.",
  R=("My mom", "bake"), B=("They", "play"), C=("The twins", "swim"), D=("My little sister", "sing"), E=("We", "help"), F=("His uncle", "fix"))
RV(7, 81, "DF", fx=True, why="정답 위치가 B·D·E·F 모두 ②였다. 수정 예시에서 D와 F를 주어가 두세 낱말인 문장으로 바꿔 정답이 ④와 ③이 되게 했다.")

X(7, 82, r="can 뒤에는 주어가 무엇이든 동사원형을 쓴다. -s가 붙은 꼴, to + 동사, -ing형은 올 수 없다.",
  n=["동사원형 drive로 시작하므로", "can 뒤에는 jumps가 아니라 jump를 써야 하므로", "동사원형 cook으로 시작하므로", "동사원형 write이므로", "동사원형 sing으로 시작하므로"],
  st="① Can + 주어 뒤의 빈칸에는 동사원형으로 시작하는 말만 들어간다. → ② 보기마다 첫 낱말이 동사원형인지 본다. → ③ {0} 정답은 {n}.",
  R="jumps는 -s가 붙은 꼴이다.", B="plays는 -s가 붙은 꼴이다.", C="to drive는 to가 붙은 꼴이다.", D="playing은 -ing가 붙은 꼴이다.", E="speaks는 -s가 붙은 꼴이다.", F="draws는 -s가 붙은 꼴이다.")

X(7, 83, r="‘~할 수 있니?’는 Can + 주어 + 동사원형 ~?으로 쓴다. can에는 -s를 붙이지 않고, Do를 함께 쓰지 않는다.",
  n=["can을 주어 앞으로 옮기지 않았고 climbs도 원형이 아니므로", "can을 주어 앞으로 옮기지 않았으므로", "Can + 주어 + 동사원형으로 바르게 옮겼으므로", "can 뒤에는 climbs가 아니라 climb을 써야 하므로", "can에는 -s를 붙이지 않고 climbs도 원형이 아니므로"],
  st="① ‘~할 수 있니?’라고 묻는 말이므로 Can을 문장 맨 앞에 둔다. Cans나 Do로 시작하는 것, 주어로 시작하는 것을 지운다. → ② 주어({0}) 뒤의 동사가 원형({1})인지 본다. → ③ 정답은 {n}.",
  R=("he", "climb"), B=("they", "carry"), C=("you", "ride"), D=("your dog", "swim"), E=("she", "sing"), F=("Tom", "speak"))
RV(7, 83, "D", fx=True, why="우리말의 주어(그들은)가 B와 같았다. 수정 예시에서 ‘너의 개는’으로 바꿨다.")
RV(7, 83, "E", fx=True, why="정답 위치(③)가 원문항·D와 같았다. 수정 예시에서 ②와 ③의 순서를 바꿔 정답을 ②로 옮겼다.")

X(7, 84, r="Can + 주어 ~? 질문에는 Yes, 대명사 + can. / No, 대명사 + can't.로 답한다. 질문의 주어를 알맞은 대명사로 받고(you → I), Yes에는 can, No에는 can't를 짝짓는다.",
  n=["질문의 you는 I로 받아야 하므로", "질문의 you는 I로 받아야 하므로", "질문의 you는 I로 받아야 하므로", "you를 I로 받고 Yes에 can을 짝지었으므로", "No 뒤에는 can이 아니라 can't를 써야 하므로"],
  st="① 질문의 주어를 대답에서 무엇으로 받는지 정한다: {0}. → ② Yes에는 can, No에는 can't를 짝짓는다. be동사나 do/does로는 답하지 않는다. → ③ 둘 다 맞는 것은 {a}",
  R="you → I", B="your friends → they", C="she → she", D="Tom → he", E="Mina → she", F="they → they")
RV(7, 84, "D", fx=True, why="수정 예시에서 성별 설명(Tom은 남학생입니다.)을 지웠는데도 그 설명이 있어야 가를 수 있는 보기(② Yes, she can.)가 남아 있었다. ②를 Yes, they can.으로 바꿨다.")

X(7, 85, r="can, can't, cannot 뒤에는 동사원형을 쓴다(be동사는 be). can에는 -s를 붙이지 않고, 뒤에 to나 -s가 붙은 동사를 쓰지 않는다.",
  n=["can 뒤에 동사원형 drive를 썼으므로", "can 뒤에는 are가 아니라 원형 be를 써야 하므로", "can't 뒤에 동사원형 ride를 썼으므로", "cannot 뒤에 동사원형 speak를 썼으므로", "can 뒤에 be동사의 원형 be를 썼으므로"],
  st="① 문장마다 can/can't/cannot 바로 뒤의 말을 본다. → ② 그 자리에 동사원형이 왔는지, can 자체에 -s가 붙지 않았는지 확인한다. → ③ {0} 정답은 {n}.",
  R="②는 can 뒤에 are를 썼다(원형은 be).", B="⑤는 can 뒤에 to fix를 썼다.", C="④는 can 뒤에 to sing을 썼다.", D="③은 can 뒤에 plays를 썼다.", E="①은 can 뒤에 am을 썼다(원형은 be).", F="②는 can에 -s를 붙였다.")

X(7, 86, r="뒤에 동사원형이 있고 둘째 문장이 할 수 없는 까닭을 말하면 can't(~할 수 없다)를 쓴다. be동사 꼴(isn't, aren't, am not, were) 뒤에는 동사원형이 올 수 없다.",
  n=["‘빨리 달릴 수 없다’는 뜻이고 뒤에 동사원형 run이 오므로", "am not은 I에만 쓰고 뒤에 run이 올 수 없으므로", "They에는 doesn't를 쓸 수 없으므로", "isn't 뒤에는 동사원형 run이 올 수 없으므로", "were 뒤에는 동사원형 run이 올 수 없으므로"],
  st="① 빈칸 뒤에 동사원형({0})이 있으므로 be동사 꼴을 지운다. → ② 둘째 문장(‘{1}’)이 그 까닭을 말하므로 ‘~할 수 없다’는 뜻이 필요하다. → ③ 정답은 {a}.",
  R=("run", "아주 느리다"), B=("fly", "나는 새가 아니다"), C=("drive", "겨우 열 살이다"), D=("see", "너무 어둡다"), E=("lift", "너무 무겁다"), F=("swim", "물을 무서워한다"))

X(7, 87, r="Can + 주어 뒤에는 동사원형을 쓴다. -s, -ing, to가 붙은 꼴이나 be동사 + 동사원형은 올 수 없다.",
  n=["can 뒤에는 -s를 붙인 꼴을 쓰지 않으므로", "-ing형은 올 수 없으므로", "Can + 주어 뒤에 동사원형 dance가 알맞으므로", "to + 동사는 올 수 없으므로", "be동사와 동사원형을 함께 쓸 수 없으므로"],
  st="① 문장이 Can + 주어({0})로 시작하므로 빈칸에는 동사원형이 온다. → ② -s, -ing, to가 붙은 꼴과 be동사가 붙은 꼴을 지운다. → ③ 남는 것은 {a}.",
  R="you", B="Tom", C="Leo", D="your mom", E="they", F="Mina")

X(7, 88, r="‘~할 수 있니?’는 Can + 주어 + 동사원형 ~?으로 쓴다. be동사의 원형은 be이므로 can 뒤에는 is/are가 아니라 be를 쓴다. Do나 Are를 함께 쓰지 않는다.",
  n=["‘너는 조용하니?’라는 뜻이라 ‘~할 수 있니’가 빠졌으므로", "can 뒤에는 is가 아니라 원형 be를 써야 하므로", "can 뒤에는 are가 아니라 원형 be를 써야 하므로", "Can + 주어 + be로 바르게 옮겼으므로", "‘~할 수 있니’는 Do가 아니라 Can으로 물어야 하므로"],
  st="① ‘~할 수 있니?’이므로 Can + 주어({0})로 시작한다. → ② ‘{1}’는 be동사 + {2}(으)로 나타내는데, can 뒤에서는 be동사를 원형 be로 쓴다. → ③ 정답은 {n}.",
  R=("you", "조용히 하다", "quiet"), B=("we", "조심하다", "careful"), C=("Mina", "준비되다", "ready"), D=("he", "친절하다", "kind"), E=("she", "행복해지다", "happy"), F=("they", "친구가 되다", "friends"))
RV(7, 88, "E", v="수정(내용)", why="정답 ③ 유일 확인. 다만 우리말과 문장(Can she be ready?)이 C(Can Mina be ready by six?)와 형용사가 같고 정답 위치(③)도 같다(유형 간 중복).", fix="형용사를 바꾸고 정답 위치를 옮겨")
RV(7, 88, "F", v="수정(내용)", why="정답 ⑤ 유일 확인. 다만 우리말과 문장(Can they be quiet?)이 원문항(Can you be quiet?)에서 주어만 바꾼 것이고, 정답 위치(⑤)가 B와 같다.", fix="다른 말로 바꾸고 정답 위치를 옮겨")

X(7, 89, r="조동사 can 뒤에는 주어의 인칭·수와 관계없이 동사원형을 쓴다. 3인칭 단수 주어여도 can이 있으면 동사에 -s를 붙이지 않는다.",
  n=["He는 3인칭이고, 인칭이 아니라 can 때문에 s를 붙이지 않으므로", "조동사 can 뒤에는 동사원형을 쓰므로", "목적어는 동사 모양과 관계없으므로", "문장 부호는 동사 모양과 관계없으므로", "play도 can이 없으면 plays가 되므로"],
  st="① can을 빼고 읽어 본다: {0} 주어가 3인칭 단수라 동사에 s가 붙는다. → ② can을 넣으면 {1} can 뒤의 동사는 주어와 관계없이 원래 모양으로 돌아간다. → ③ can을 이유로 든 것은 {n}.",
  R=("He plays the guitar.", "He can play the guitar."), B=("Tom speaks English.", "Tom can speak English."), C=("Mina reads this map.", "Mina can read this map."), D=("She sings well.", "She can sing well."),
  E=("My brother helps you.", "My brother can help you."), F=("The dog runs fast.", "The dog can run fast."))
RV(7, 89, "B", v="수정(내용)", why="정답 ③ 유일 확인. 다만 오답이 문장과 관계없는 짧은 일반론(‘마침표가 있기 때문이다’ 등)이고 정답만 길고 구체적이어서 길이만으로 답이 드러난다. 동사(read)도 C와 같다.", fix="동사를 바꾸고, 오답을 문장 속 낱말을 두고 말하는 오해로")
RV(7, 89, "C", v="수정(내용)", why="정답 ④ 유일 확인. 다만 오답이 한 줄짜리 짧은 말이고 정답만 길어 길이만으로 답이 드러난다. 정답의 용어(본동사, 기본형)도 원문항(동사의 원래 모양)과 다르다.", fix="오답을 이유를 갖춘 문장으로 늘리고 정답의 말을 원문항에 맞춰")

X(7, 90, r="Can + 주어 + 동사원형 ~? 형태인지 본다. can에는 -s를 붙이지 않고(Cans ×), can 뒤의 동사는 -s나 to 없이 원형으로 쓴다(be동사는 be).",
  pre=["문장별 판정: (A) O. can 뒤에 원형 jump를 썼다. (B) X. can 뒤에는 원형 fix를 쓴다. (C) X. can에는 -s를 붙이지 않는다. (D) O. can 뒤에 원형 speak를 썼다. (E) O. can 뒤에 be동사의 원형 be를 썼다."],
  k="밑줄 친 부분이 옳은 문장은 (A), (D), (E)이다.", n=["(B), (C)가 틀린 문장이므로", "(C)가 틀린 문장이므로", "(A), (D), (E)가 모두 옳은 문장이므로", "(B), (C)가 틀린 문장이므로", "(B)가 틀린 문장이므로"],
  st="① 문장마다 밑줄 친 말이 Can인지, can 뒤의 동사인지 본다. → ② Can에는 -s를 붙이지 않고, can 뒤의 동사는 원형이어야 한다. {0} → ③ 옳은 것만 모으면 {a}",
  R="(A) O, (B) fixes(X), (C) Cans(X), (D) O, (E) O.", B="(A) reads(X), (B) O, (C) O, (D) Cans(X), (E) O.", C="(A) O, (B) O, (C) runs(X), (D) Cans(X), (E) O.", D="(A) O, (B) rides(X), (C) O, (D) Cans(X), (E) O.",
  E="(A) runs(X), (B) O, (C) Cans(X), (D) O, (E) O.", F="(A) O, (B) swims(X), (C) O, (D) O, (E) Cans(X).")
RV(7, 90, "CF", v="수정(내용)", why="정답 유일 확인. 다만 문장이 원문항의 절반쯤으로 짧고(Can she dance? / Can I help? 등), 보기에 두 개 조합이 섞여 있다(원문항은 모두 세 개 조합). 밑줄과 줄바꿈이 없고 발문도 다르다.", fix="문장을 원문항 길이로, 보기를 모두 세 개 조합으로, 밑줄·발문을 원문항대로")
